arguments.output:
{
  "updated":{{vars.steps.find_ztpfMetadataSource 
              or vars.steps.find_ztpfTemplate 
              or vars.steps.find_ztpfAutomationAction 
              or vars.steps.find_ztpfAutomationProfile
              or vars.steps.find_ztpfAutomationProfileStep
            }} 
}

arguments.record_ids:
{%- set in_field = vars.input.params['record_ids'] -%}
{%- set ret = "" -%}

{%- if in_field not in ['',None] -%}
  {%- if in_field is sequence 
        and in_field is not string 
        and in_field is not integer -%}
    {%- set ret = in_field -%}
  {%- else -%}
    {%- set cmt = in_field | regex_replace('[,\n]+', ',') -%}
    {%- set ret = cmt.split(',') -%}
  {%- endif -%}
{%- endif -%}
{{ret|unique}}
